*{box-sizing:border-box} :root{--ink:#283c31;--muted:#758077;--cream:#fffaf4;--paper:#fff;--green:#466a51;--green-dark:#355440;--pink:#f5d5cc;--coral:#df816f;--line:#eee8df;--yellow:#f6e8ac} html{scroll-behavior:smooth} body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px}button,input{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.page-shell{max-width:1180px;margin:auto;padding:0 40px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eee8df}.brand{display:flex;align-items:center;gap:9px;font-weight:700;font-size:20px;letter-spacing:-.7px}.brand-mark{color:#e18474;font-size:25px;line-height:1}.topbar nav{display:flex;gap:38px;color:#777f77;font-size:13px}.topbar nav a:hover,.text-button:hover{color:var(--coral)}.saved-link{border:1px solid #e8e1d8;background:#fffaf4;color:var(--ink);padding:10px 15px;border-radius:22px;font-size:12px;display:flex;align-items:center;gap:7px}.saved-link span:first-child{color:#d97c6d;font-size:17px}.saved-link b{background:#e8eee6;color:var(--green);font-size:10px;border-radius:99px;padding:3px 6px}.intro{min-height:345px;display:grid;grid-template-columns:1fr 1fr;align-items:center;padding:36px 0 42px}.intro-copy{padding-left:12px}.eyebrow,.section-kicker{font-size:10px;font-weight:700;letter-spacing:1.55px;color:#8b9a83}.eyebrow{display:flex;gap:8px;align-items:center;margin-bottom:12px}.sparkle{font-size:17px;color:#dfa283}h1,h2,p{margin-top:0}h1{font-family:'Playfair Display',serif;font-size:54px;line-height:1.04;letter-spacing:-1.7px;margin-bottom:14px;font-weight:700}h1 em,.results-heading h2 em{font-weight:600;color:#c97867} .intro-copy>p{font-size:15px;line-height:1.65;color:#798079;max-width:370px;margin-bottom:20px}.intro-notes{display:flex;gap:18px;font-size:10px;color:#758078}.intro-notes span:first-child{color:#658066}.hero-art{position:relative;width:375px;height:267px;justify-self:center;display:flex;align-items:center;justify-content:center}.hero-art img{height:226px;width:274px;object-fit:cover;border-radius:48% 52% 47% 53% / 43% 46% 54% 57%;transform:rotate(3deg);z-index:1;box-shadow:0 18px 35px #604d351c}.art-sun{position:absolute;background:#f6e9b9;width:220px;height:220px;border-radius:50%;right:21px;top:8px}.art-sticker{position:absolute;z-index:2;background:white;box-shadow:0 5px 16px #49534218;border-radius:50%;width:86px;height:86px;text-align:center;display:grid;align-content:center;font-size:10px;line-height:1.35;color:#657665;transform:rotate(-9deg)}.art-sticker span{font-size:15px;color:#df856f}.sticker-top{top:12px;left:8px}.sticker-bottom{bottom:0;right:5px;transform:rotate(8deg);background:#f5d6cd}.art-flower{position:absolute;z-index:2;color:#de8a74}.flower-one{font-size:26px;right:21px;top:34px}.flower-two{font-size:17px;left:46px;bottom:26px;color:#81967d}.kitchen-panel{background:white;border:1px solid #f0ebe4;border-radius:15px;padding:28px 32px 23px;box-shadow:0 9px 22px #54432c08}.panel-heading,.results-heading{display:flex;justify-content:space-between;align-items:center}.section-kicker{font-size:9px;letter-spacing:1.5px;margin-bottom:7px}.panel-heading h2,.results-heading h2{font-family:'Playfair Display',serif;font-size:25px;letter-spacing:-.5px;margin:0}.step-pill{border-radius:20px;background:#f4f6f1;color:#788678;padding:8px 12px;font-size:10px}.step-pill span{background:#72886e;color:white;display:inline-grid;place-items:center;width:17px;height:17px;border-radius:50%;margin-right:5px}.panel-subtitle{color:#8b918a;font-size:12px;margin:7px 0 17px}.ingredient-form{height:47px;border:1px solid #e9e9e2;border-radius:8px;display:flex;align-items:center;padding:0 6px 0 13px}.input-icon{font-size:23px;color:#8f9a8b;transform:rotate(-20deg);margin-right:10px}.ingredient-form input{border:0;outline:0;flex:1;min-width:0;color:var(--ink);font-size:12px;background:transparent}.ingredient-form input::placeholder{color:#a7aaa3}.add-button{border:0;color:#526c54;background:#edf2eb;border-radius:6px;padding:10px 13px;font-size:11px;font-weight:600}.add-button span{font-size:15px;margin-left:5px}.ingredient-row{min-height:45px;padding:9px 0 7px;display:flex;justify-content:space-between;align-items:center;gap:10px}.ingredient-list{display:flex;gap:7px;flex-wrap:wrap}.ingredient-chip{display:flex;align-items:center;gap:7px;padding:7px 10px;border-radius:99px;background:#f4f5ef;font-size:11px;color:#5e705e}.ingredient-chip button{border:0;background:none;color:#94a08e;padding:0;font-size:15px;line-height:10px}.ingredient-chip button:hover{color:#d47768}.text-button{border:0;background:none;color:#92958f;font-size:10px;padding:5px;white-space:nowrap}.pantry-row{border-top:1px dashed #eeeae3;padding-top:12px;display:flex;align-items:center;gap:13px;min-height:39px}.pantry-label{font-size:9px;letter-spacing:1.2px;color:#a6a49b;font-weight:700}.quick-add{display:flex;gap:7px;flex-wrap:wrap}.quick-chip{border:1px solid #ecebe4;background:#fff;border-radius:99px;padding:5px 10px;color:#848980;font-size:10px}.quick-chip:hover{border-color:#9bb198;color:#526c54;background:#f7faf6}.search-row{display:flex;justify-content:space-between;align-items:center;padding-top:14px}.helper-note{font-size:10px;color:#a0a39b}.helper-note span{color:#d39767}.primary-button{background:#496c53;color:white;border:0;border-radius:7px;padding:12px 17px;font-size:11px;font-weight:600;box-shadow:0 4px 9px #486c5324}.primary-button:hover{background:#355440;transform:translateY(-1px)}.primary-button span{font-size:15px;margin-left:12px}.recipes-section{padding:42px 0 30px}.results-heading h2{font-size:26px}.results-heading h2 em{font-style:italic}.surprise-button{border:1px solid #e9e3da;background:#fff;border-radius:22px;padding:9px 14px;color:#71796f;font-size:11px}.surprise-button span{color:#d88472;font-size:17px;vertical-align:-2px;margin-right:5px}.status-line{display:flex;align-items:center;gap:7px;color:#969b92;font-size:10px;margin:10px 0 16px}.status-dot{height:6px;width:6px;border-radius:100%;background:#a2b896}.recipe-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:17px}.recipe-card{border:1px solid #eee9e1;background:white;border-radius:11px;overflow:hidden;transition:transform .2s,box-shadow .2s;cursor:pointer;min-width:0}.recipe-card:hover{transform:translateY(-3px);box-shadow:0 12px 24px #54432c13}.recipe-image{position:relative;height:155px;background:#ebece4;overflow:hidden}.recipe-image img{width:100%;height:100%;object-fit:cover;transition:transform .4s}.recipe-card:hover .recipe-image img{transform:scale(1.04)}.match-badge{position:absolute;left:11px;top:11px;background:#fffdf7eF;border-radius:99px;padding:6px 9px;color:#557254;font-size:9px;font-weight:600;box-shadow:0 2px 6px #0000000d}.save-button{position:absolute;right:10px;top:9px;width:30px;height:30px;border:0;border-radius:50%;background:#fffdf7;color:#9e8d83;font-size:17px}.save-button.is-saved{color:#d6796b}.card-content{padding:13px 14px 14px}.card-meta{display:flex;align-items:center;gap:8px;color:#9a9d94;font-size:9px;margin-bottom:7px}.card-meta .dot-sep{width:3px;height:3px;background:#d2c9bc;border-radius:50%}.card-content h3{font-family:'Playfair Display',serif;font-size:16px;line-height:1.25;margin:0 0 7px;letter-spacing:-.2px}.card-content p{color:#878e85;font-size:10px;line-height:1.5;margin:0 0 11px;min-height:30px}.card-footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #f1eee8;padding-top:10px}.ingredient-count{font-size:9px;color:#788477}.view-recipe{font-size:10px;font-weight:600;color:#557356}.view-recipe span{color:#d2826f;margin-left:4px}.more-row{display:flex;justify-content:space-between;align-items:center;margin:19px 2px 0;color:#9a9d95;font-size:10px}.more-row .text-button{font-size:10px;color:#698268}.more-row .text-button span{font-size:14px;margin-left:6px}footer{min-height:72px;border-top:1px solid #eee8df;display:flex;align-items:center;justify-content:space-between;color:#a0a197;font-size:10px}.footer-brand{font-size:15px;color:var(--ink)}.footer-brand .brand-mark{font-size:20px}.footer-heart{color:#c17d6e}.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;z-index:10;padding:18px}.modal.open{display:flex}.modal-backdrop{position:absolute;inset:0;background:#26352bc4;backdrop-filter:blur(3px)}.modal-card{position:relative;background:#fffaf4;width:min(520px,100%);max-height:90vh;overflow:auto;border-radius:16px;box-shadow:0 25px 80px #10201566;z-index:1}.modal-close{position:absolute;top:12px;right:13px;border:0;background:#fff;border-radius:50%;height:33px;width:33px;font-size:23px;color:#526253;z-index:2}.modal-hero{height:205px;width:100%;object-fit:cover;display:block}.modal-body{padding:21px 25px 25px}.modal-body h2{font:700 29px 'Playfair Display',serif;margin:5px 0 8px}.modal-body>p{color:#7d867b;line-height:1.6;font-size:12px}.modal-facts{display:flex;gap:12px;color:#63745f;font-size:11px;margin:13px 0 18px}.modal-body h3{font:600 16px 'Playfair Display',serif;margin:17px 0 9px}.modal-body ul,.modal-body ol{padding-left:20px;color:#69756b;font-size:12px;line-height:1.8}.online-link{display:inline-block;background:var(--green);color:white;padding:11px 15px;border-radius:7px;font-size:11px;font-weight:600;margin-top:8px}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);background:#304c37;color:white;padding:11px 17px;border-radius:9px;box-shadow:0 7px 20px #0002;font-size:12px;opacity:0;pointer-events:none;transition:.25s;z-index:15}.toast.show{opacity:1;transform:translate(-50%,0)}.empty-state{grid-column:1/-1;padding:30px;text-align:center;background:white;border:1px dashed #e6e1d8;border-radius:12px;color:#8b9488}.empty-state strong{display:block;color:#546c54;font:600 19px 'Playfair Display',serif;margin-bottom:7px}.loading{grid-column:1/-1;padding:40px;text-align:center;color:#7a8a78}.loading:before{content:'✿';font-size:22px;color:#d47e6d;display:block;animation:spin 2s infinite linear;margin-bottom:8px}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:750px){.page-shell{padding:0 20px}.topbar{height:68px}.topbar nav{display:none}.intro{grid-template-columns:1fr;padding:37px 0 29px;text-align:center}.intro-copy{padding:0}.eyebrow{justify-content:center}h1{font-size:46px}.intro-copy>p{margin-left:auto;margin-right:auto;font-size:14px}.intro-notes{justify-content:center;gap:12px;font-size:9px}.hero-art{width:320px;height:220px;margin:12px auto 0}.hero-art img{width:235px;height:190px}.art-sun{width:190px;height:190px}.sticker-top{left:0}.sticker-bottom{right:0}.kitchen-panel{padding:23px 18px 18px}.panel-heading h2{font-size:21px}.step-pill{font-size:9px;padding:7px}.panel-subtitle{line-height:1.5}.ingredient-form{height:auto;min-height:46px}.ingredient-form input{font-size:11px}.add-button{padding:9px 10px;font-size:10px}.ingredient-row{align-items:flex-start}.pantry-row{align-items:flex-start}.pantry-label{padding-top:7px}.quick-add{gap:5px}.quick-chip{padding:5px 8px}.search-row{align-items:flex-start;gap:10px}.helper-note{line-height:1.5;max-width:180px}.primary-button{padding:11px 12px;white-space:nowrap;font-size:10px}.recipes-section{padding-top:34px}.results-heading h2{font-size:22px}.surprise-button{font-size:10px;padding:8px 10px}.recipe-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.recipe-image{height:135px}.card-content{padding:11px}.card-content h3{font-size:15px}.card-content p{font-size:9px}.more-row{gap:8px}.more-row>span{max-width:160px;line-height:1.5}footer{gap:8px;flex-wrap:wrap;padding:16px 0}.footer-heart{display:none}}
@media(max-width:420px){.page-shell{padding:0 14px}.saved-link{padding:8px 10px}.brand{font-size:18px}.intro-notes{flex-direction:column;gap:5px}.panel-heading h2{font-size:19px}.step-pill{font-size:0}.step-pill span{font-size:10px;margin:0}.recipe-grid{gap:9px}.recipe-image{height:115px}.match-badge{left:6px;top:7px;font-size:8px;padding:5px 7px}.save-button{right:6px;top:6px;height:27px;width:27px}.card-meta{font-size:8px;gap:5px}.card-content h3{font-size:14px}.ingredient-form input::placeholder{font-size:10px}.add-button{font-size:0}.add-button span{font-size:19px;margin:0}.more-row .text-button{font-size:9px}}

const API='https://www.themealdb.com/api/json/v1/1/';
const fallbackRecipes=[
 {id:'local-1',title:'Creamy spinach & feta eggs',image:'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=700&q=80',time:'20 min',category:'Breakfast',description:'Soft, jammy eggs nestled into garlicky greens with a little salty feta.',ingredients:['eggs','spinach','feta','olive oil','garlic'],steps:['Wilt spinach with a drizzle of olive oil and minced garlic.','Make little wells in the greens and crack in the eggs. Cover and cook until the whites are set.','Crumble feta over the top, season, and serve with toast.'],url:'https://www.bbcgoodfood.com/recipes/spinach-feta-shakshuka'},
 {id:'local-2',title:'Tomato & feta toast',image:'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=700&q=80',time:'15 min',category:'Lunch',description:'Juicy tomatoes, creamy feta and herbs piled onto golden sourdough.',ingredients:['tomato','feta','bread','olive oil','lemon'],steps:['Toast thick slices of bread until crisp and golden.','Roughly chop tomatoes and toss with olive oil, lemon, salt and pepper.','Spoon the tomatoes onto toast, crumble over feta and finish with herbs.'],url:'https://www.bbcgoodfood.com/recipes/tomato-feta-salad'},
 {id:'local-3',title:'Green goddess chickpea bowl',image:'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=700&q=80',time:'25 min',category:'Dinner',description:'A feel-good bowl with crisp greens, chickpeas and a bright lemony dressing.',ingredients:['chickpeas','spinach','tomato','lemon','yogurt'],steps:['Drain and rinse the chickpeas, then season with olive oil, salt and pepper.','Whisk yogurt with lemon juice, a little water and chopped herbs.','Layer greens, chickpeas and tomatoes in a bowl. Drizzle generously with dressing.'],url:'https://www.loveandlemons.com/chickpea-salad/'},
 {id:'local-4',title:'Easy garden omelette',image:'https://images.unsplash.com/photo-1510693206972-df098062cb71?auto=format&fit=crop&w=700&q=80',time:'12 min',category:'Quick & easy',description:'A fluffy, golden omelette that welcomes just about any veg in the crisper.',ingredients:['eggs','spinach','tomato','cheese','butter'],steps:['Beat eggs with a pinch of salt and pepper until combined.','Melt butter in a pan and cook the eggs gently, drawing the edges inward.','Add spinach, diced tomato and cheese. Fold in half and serve while warm.'],url:'https://www.bbcgoodfood.com/recipes/basic-omelette'},
 {id:'local-5',title:'Roasted tomato pasta',image:'https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=700&q=80',time:'30 min',category:'Dinner',description:'A simple, comforting pasta with sweet tomatoes, garlic and a shower of parmesan.',ingredients:['tomato','pasta','garlic','olive oil','parmesan'],steps:['Roast chopped tomatoes and garlic with olive oil at 220°C / 425°F until jammy.','Meanwhile, cook pasta in well-salted water until just al dente.','Toss pasta with roasted tomatoes and a splash of pasta water. Finish with parmesan.'],url:'https://www.bbcgoodfood.com/recipes/roasted-tomato-sauce'},
 {id:'local-6',title:'Crispy chickpea salad',image:'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=700&q=80',time:'25 min',category:'Lunch',description:'Crunchy golden chickpeas make this fresh, colorful salad extra satisfying.',ingredients:['chickpeas','spinach','tomato','cucumber','lemon'],steps:['Pat chickpeas dry, toss with oil and paprika, then roast until crisp.','Chop the vegetables and toss with lemon juice and olive oil.','Top the salad with warm chickpeas and enjoy.'],url:'https://www.loveandlemons.com/chickpea-salad/'}
];
const quickItems=['Eggs','Spinach','Tomato','Cheese','Chickpeas','Pasta','Avocado','Rice'];
const $=s=>document.querySelector(s);
let ingredients=['eggs','spinach','feta','tomato'],recipes=[],saved=JSON.parse(localStorage.getItem('littleThymeSaved')||'[]'),showSaved=false,toastTimer;
const norm=s=>s.toLowerCase().trim().replace(/s$/,'');
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function renderIngredients(){ $('#ingredientList').innerHTML=ingredients.map((x,i)=>`<span class="ingredient-chip">${escapeHtml(cap(x))}<button aria-label="Remove ${escapeHtml(x)}" data-remove="${i}">×</button></span>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{ingredients.splice(+b.dataset.remove,1);renderIngredients()});}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
function renderQuick(){ $('#quickAdd').innerHTML=quickItems.map(x=>`<button class="quick-chip" data-quick="${x}">＋ ${x}</button>`).join('');document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>addIngredient(b.dataset.quick));}
function addIngredient(value){const x=value.trim().replace(/\s+/g,' ');if(!x)return;if(ingredients.some(i=>norm(i)===norm(x))){notify(`${cap(x)} is already in your kitchen`);return}ingredients.push(x.toLowerCase());renderIngredients();$('#ingredientInput').value='';}
function matchScore(r){const found=ingredients.filter(i=>r.ingredients?.some(x=>norm(x).includes(norm(i))||norm(i).includes(norm(x))));return {found:found.length,total:ingredients.length,percent:Math.round(found.length/Math.max(1,ingredients.length)*100)}}
function renderCards(list){recipes=list;const shown=showSaved?list.filter(r=>saved.includes(String(r.id))):list;$('#recipeGrid').innerHTML=shown.length?shown.map((r,index)=>{const m=matchScore(r);return `<article class="recipe-card" data-card="${index}"><div class="recipe-image"><img src="${escapeHtml(r.image||'')}" alt="${escapeHtml(r.title)}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=700&q=80'"><span class="match-badge">${m.found?`${m.found} ingredient${m.found===1?'':'s'} match`:'A pantry-friendly idea'}</span><button class="save-button ${saved.includes(String(r.id))?'is-saved':''}" data-save="${escapeHtml(String(r.id))}" aria-label="${saved.includes(String(r.id))?'Unsave':'Save'} recipe">${saved.includes(String(r.id))?'♥':'♡'}</button></div><div class="card-content"><div class="card-meta"><span>${escapeHtml(r.category||'A good thing')}</span><span class="dot-sep"></span><span>${escapeHtml(r.time||'30 min')}</span></div><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.description||'A lovely recipe to make with things you have on hand.')}</p><div class="card-footer"><span class="ingredient-count">${m.found} of your ingredients</span><span class="view-recipe">Get cooking <span>→</span></span></div></div></article>`}).join(''):'<div class="empty-state"><strong>No saved recipes just yet</strong>Tap the little heart on anything that looks lovely.</div>';
 document.querySelectorAll('.recipe-card').forEach(c=>c.onclick=()=>openRecipe(recipes[+c.dataset.card]));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleSave(b.dataset.save)});$('#savedCount').textContent=saved.length;$('#savedToggle').classList.toggle('active',showSaved);}
function toggleSave(id){id=String(id);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('littleThymeSaved',JSON.stringify(saved));renderCards(recipes);notify(saved.includes(id)?'Saved for a hungry day ♡':'Removed from your saved recipes');}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function setStatus(msg,loading=false){$('#statusText').textContent=msg;$('#statusLine').classList.toggle('is-loading',loading)}
function titleForSearch(){if(!ingredients.length)return 'Let’s find <em>something good.</em>';return `Your fridge has <em>potential.</em>`}
function fallbackSuggestions(){let ranked=fallbackRecipes.map(r=>({...r,_score:matchScore(r).found})).sort((a,b)=>b._score-a._score);if(!ingredients.length)return ranked.slice(0,3);const relevant=ranked.filter(r=>r._score>0);return (relevant.length?relevant:ranked).slice(0,3)}
function mealIngredients(meal){return Array.from({length:20},(_,i)=>meal[`strIngredient${i+1}`]).filter(Boolean).map(x=>x.trim()).filter(Boolean)}
function mealToRecipe(m){const ing=mealIngredients(m),steps=(m.strInstructions||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return {id:String(m.idMeal),title:m.strMeal,image:m.strMealThumb,category:m.strCategory||'From the web',time:'35 min',description:`A real ${m.strCategory?.toLowerCase()||'home-cooked'} recipe from ${m.strArea||'the kitchen'} — ready for your table.`,ingredients:ing,steps,url:m.strSource||`https://www.themealdb.com/meal/${m.idMeal}`}}
async function onlineRecipes(){const keys=ingredients.slice(0,3).map(i=>i.trim().toLowerCase().replace(/\s+/g,'_'));const lists=await Promise.all(keys.map(async k=>{try{const res=await fetch(`${API}filter.php?i=${encodeURIComponent(k)}`);if(!res.ok)throw 0;return (await res.json()).meals||[]}catch{return []}}));const all=new Map();lists.flat().forEach(m=>all.set(m.idMeal,m));if(!all.size)return [];const candidates=[...all.values()].sort((a,b)=>{const ac=keys.filter(k=>a.strMeal.toLowerCase().includes(k.replaceAll('_',' '))).length;const bc=keys.filter(k=>b.strMeal.toLowerCase().includes(k.replaceAll('_',' '))).length;return bc-ac});const details=await Promise.all(candidates.slice(0,9).map(async m=>{try{const res=await fetch(`${API}lookup.php?i=${m.idMeal}`);return (await res.json()).meals?.[0]}catch{return null}}));return details.filter(Boolean).map(mealToRecipe).sort((a,b)=>matchScore(b).found-matchScore(a).found).slice(0,3)}
